js:
(function() {
  'use strict';

  const api = window.CardSpoke.utils;

  // Format date nicely
  function formatDate(timestamp) {
    if (!timestamp) return 'Unknown';
    const date = new Date(timestamp);
    return date.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  }

  // Add timestamps to cards
  function addTimestamps() {
    const cards = document.querySelectorAll('.card');

    cards.forEach(cardEl => {
      // Skip if already has timestamp
      if (cardEl.querySelector('.card-timestamp')) return;

      // Get card ID from data attribute or other means
      const cardId = cardEl.dataset.cardId;
      if (!cardId) return;

      const card = api.getCard(cardId);
      if (!card || !card.meta) return;

      const timestamp = document.createElement('div');
      timestamp.className = 'card-timestamp';
      timestamp.textContent = formatDate(card.meta.createdAt || card.meta.updatedAt);

      const cardBody = cardEl.querySelector('.card-body');
      if (cardBody) {
        cardBody.appendChild(timestamp);
      }
    });
  }

  // Observe for changes
  const observer = new MutationObserver(() => {
    setTimeout(addTimestamps, 100);
  });

  observer.observe(document.body, { childList: true, subtree: true });

  // Initial run
  addTimestamps();

  api.showToast('Timestamp Patch applied!', 'success');
})();
